val ANCIENT_WIKI_SEED: List<WikiSeedArticle> = listOf(
    WikiSeedArticle(
        id = "garni", category = "fortresses", sortOrder = 101, section = "ancient",
        titleEn = "Temple of Garni", titleRu = "Храм Гарни", titleHy = "Գառնի տաճար",
        bodyEn = "The temple of Garni is the only surviving Greco-Roman colonnaded building in the entire post-Soviet region and the standing emblem of pre-Christian Armenia. It rises on a triangular cliff above the Azat river gorge, 28 km east of Yerevan, most likely built in the 1st century AD by king Trdat I — the same king who later embraced Christianity. Twenty-four Ionic columns carry a pediment with carvings of atlantes; a bath-house with a Greek inscription and a mosaic floor stands nearby. The fortress around it guarded the approaches to the Ararat plain for centuries. In 1679 a great earthquake toppled the temple into a heap of drums, and it lay ruined for almost three centuries. Between 1969 and 1975 it was painstakingly reassembled — the first anastylosis in Soviet archaeology. Today Garni pairs naturally with the cliff monastery of Geghard a few kilometres upstream.",
        bodyRu = "Храм Гарни — единственное сохранившееся греко-римское колоннадное здание на всём постсоветском пространстве и живая эмблема дохристианской Армении. Он стоит на треугольной скале над ущельем реки Азат, в 28 км к востоку от Еревана; наиболее вероятно, что построен в I веке н. э. царём Трдатом I — тем самым, что позже принял христианство. Двадцать четыре ионические колонны несут фронтон с резными атлантами; рядом — баня с греческой надписью и мозаичным полом. Крепость вокруг храма веками охраняла подступы к Араратской равнине. В 1679 году сильное землетрясение сбросило храм в груду барабанов, и он лежал в руинах почти три века. В 1969–1975 годах его кропотливо собрали заново — первая анастилоза в советской археологии. Сегодня Гарни естественно дополняется скальным монастырём Гегард в нескольких километрах выше по ущелью.",
        bodyHy = "Գառնի տաճարը հետխորհրդային տարածքում պահպանված միակ հունահռոմեական սյունազարդ շինությունն է և նախաքրիստոնեական Հայաստանի խոսուն խորհրդանիշը։ Այն բարձրանում է եռանկյուն ժայռի վրա՝ Ազատ գետի կիրճի մոտ, Երևանից 28 կմ արևելք. ամենայն հավանականությամբ կառուցվել է մ.թ. 1-ին դարում Տրդատ Ա թագավորի կողմից՝ հենց նույն թագավորի, որը հետագայում ընդունեց քրիստոնեությունը։ Քսանչորս հոնիական սյուները կրում են ատլանտներով քանդակազարդ ճակտողը. մոտակայքում է հունարեն արձանագրությամբ և խճանկար հատակով բաղնիքը։ Տաճարի շուրջ ամրոցը դարեր շարունակ պահպանում էր Արարատյան դաշտի մոտեցումները։ 1679 թվականի մեծ երկրաշարժը տաճարը գցեց աղյուսակույտի, և այն գրեթե երեք դար մնաց ավերակ։ 1969–1975 թվականներին այն ջանասիրաբար վերականգնվեց՝ որպես խորհրդային հնագիտության առաջին անաստիլոզը։ Այսօր Գառնին բնականորեն համադրվում է մի քանի կիլոմետր վերև գտնվող Գեղարդ ժայռափոր վանքի հետ։"
    ),
    WikiSeedArticle(
        id = "geghard", category = "fortresses", sortOrder = 102, section = "ancient",
        titleEn = "Geghard Monastery", titleRu = "Монастырь Гегард", titleHy = "Գեղարդ վանք",
        bodyEn = "Geghard is a monastery partly carved out of the living rock of the Azat gorge, surrounded by cliffs on three sides. Its name — 'the Spear' — refers to the lance said to have wounded Christ at the crucifixion, kept here for centuries and now displayed in the museum of Etchmiadzin. The main church, Katoghike, was built in 1215 under the Zakarian princes; above it opens the rock-cut church of Avazan (1225), and the sacristy of 1240 is hewn from the cliff itself. Natural springs seep from the holy relic rock inside the complex, and acoustics of the cave chambers turn chant into resonance. The facades combine Armenian khachkars and folk crosses with delicate vine carvings. UNESCO listed Geghard together with the upper Azat valley in 2000. The road from Garni up the gorge — basalt towers, honey-coloured cliffs — is part of the experience.",
        bodyRu = "Гегард — монастырь, частично высеченный в живой скале ущелья Азата, с трёх сторон окружённый обрывами. Название — «Копьё» — отсылает к копью, которым, по преданию, был ранен Христос на распятии; его хранили здесь веками, сейчас оно в музее Эчмиадзина. Главная церковь, Катогике, построена в 1215 году при князьях Закарянах; над ней открывается высеченная в скале церковь Авазан (1225), а ризница 1240 года прорублена прямо в обрыве. Из скалы со святой реликвией внутри комплекса бьют родники, а акустика пещерных залов превращает песнопение в гулкое эхо. Фасады сочетают армянские хачкары и народные кресты с изысканной резьбой виноградной лозы. ЮНЕСКО внесло Гегард вместе с верхней долиной Азата в список наследия в 2000 году. Дорога от Гарни вверх по ущелью — базальтовые башни, медовые обрывы — часть впечатления.",
        bodyHy = "Գեղարդը մասամբ կենդանի ժայռի մեջ փորված վանք է Ազատի կիրճում՝ երեք կողմից շրջապատված ժայռերով։ Անունը՝ «Գեղարդ» (նիզակ), վերաբերում է այն նիզակին, որով, ավանդության համաձայն, Քրիստոսը վիրավորվել է խաչելության ժամանակ. այն դարերով պահվել է այստեղ, իսկ հիմա ցուցադրվում է Էջմիածնի թանգարանում։ Գլխավոր եկեղեցին՝ Կաթողիկեն, կառուցվել է 1215 թվականին Զաքարյան իշխանների օրոք. նրա վերևում բացվում է ժայռի մեջ փորված Ավազան եկեղեցին (1225), իսկ 1240 թվականի ժամեստը փորված է հենց ժայռի մեջ։ Համալիրի ներսում սուրբ մասունքի ժայռից բխում են աղբյուրներ, իսկ քարանձավային դահլիճների ակուստիկան երգեցողությունը դարձնում է անձայն հնչյուն։ Ճակատները հայկական խաչքարերն ու ժողովրդական խաչերը համադրում են նրբագեղ որթատունկի քանդակների հետ։ ՅՈՒՆԵՍԿՕ-ն Գեղարդը Ազատի վերին հովտի հետ ընդգրկել է ժառանգության ցուցակում 2000 թվականին։ Գառնիից դեպի վերև ձգվող ճանապարհը՝ բազալտե աշտարակներ, մեղրագույն ժայռեր, նույնպես տպավորության մաս է։"
    ),
    WikiSeedArticle(
        id = "zvartnots", category = "fortresses", sortOrder = 103, section = "ancient",
        titleEn = "Zvartnots Cathedral", titleRu = "Собор Звартноц", titleHy = "Զվարթնոց տաճար",
        bodyEn = "Zvartnots — 'the temple of the Vigilant Angels' — was built by Catholicos Nerses III the Builder between 641 and 653, at the spot where, tradition says, king Trdat III met Gregory the Illuminator. It was a tetraconch of extraordinary design: a three-tiered circular mass with quatrefoil core, ringed by an arcade, about 45 metres tall — nothing like it stood in the Christian world of its day. The sculpted facades showed vine scrolls and patrons; the columns bore eagle capitals. Zvartnots stood barely three centuries: a great earthquake at the turn of the 10th century brought the whole giant down, and it vanished until excavations by Toros Toramanyan in 1900–1907 raised its plan from the ground. Its image now decorates the altar wall of Etchmiadzin cathedral and the state coat of arms of Armenia. The ruins, a UNESCO site since 2000, stand between Yerevan and Etchmiadzin — near the airport that borrowed the name.",
        bodyRu = "Звартноц — «храм Бдящих Ангелов» — построил Католикос Нерсес III Строитель между 641 и 653 годами, на месте, где, по преданию, царь Трдат III встретил Григория Просветителя. Это был тетраконх необычайного замысла: трёхъярусная круглая масса с четырёхлепестковым ядром, опоясанная аркадой, высотой около 45 метров — ничего похожего не стояло в христианском мире того времени. Резные фасады несли виноградные лозы и изображения ктиторов; капители колонн украшали орлы. Звартноц простоял неполных три века: сильное землетрясение на рубеже X века обрушило исполина целиком, и он исчез до раскопок Тороса Тораманяна 1900–1907 годов, поднявших его план из земли. Сегодня изображение Звартноца украшает алтарную стену собора Эчмиадзина и герб Армении. Руины — объект ЮНЕСКО с 2000 года — стоят между Ереваном и Эчмиадзином, рядом с аэропортом, взявшим имя храма.",
        bodyHy = "Զվարթնոցը՝ «Զգոն հրեշտակների տաճարը», կառուցել է Կաթողիկոս Ներսես Գ Շինողը 641–653 թվականներին՝ այն վայրում, որտեղ, ավանդության համաձայն, Տրդատ Գ թագավորը հանդիպել է Գրիգոր Լուսավորչին։ Դա բացառիկ մտահղացմամբ տետրակոնխ էր. եռահարկ կլոր համարյա 45 մետրանոց ծավալ՝ քառաթերթ միջուկով, շրջափակված սյունաշարքով. իր ժամանակի քրիստոնեական աշխարհում նմանը չկար։ Քանդակազարդ ճակատները կրում էին որթատունկ և բարերարների պատկերներ, սյուների խոյակները՝ արծիվներ։ Զվարթնոցը կանգնած մնաց երեք դարից պակաս. 10-րդ դարի սկզբի մեծ երկրաշարժը հսկային գետնին տվեց, և այն անհետացավ մինչև Թորոս Թորամանյանի պեղումները (1900–1907), որոնք նրա հատակագիծը բարձրացրին գետնից։ Այսօր Զվարթնոցի պատկերը զարդարում է Էջմիածնի տաճարի խորանի պատը և Հայաստանի զինանշանը։ Ավերակները՝ ՅՈՒՆԵՍԿՕ-ի հուշարձան 2000 թվականից, կանգնած են Երևանի և Էջմիածնի միջև՝ տաճարի անունը կրող օդանավակայանի մոտ։"
    ),
    WikiSeedArticle(
        id = "etchmiadzin", category = "fortresses", sortOrder = 104, section = "ancient",
        titleEn = "Etchmiadzin Cathedral", titleRu = "Собор Эчмиадзин", titleHy = "Էջմիածնի տաճար",
        bodyEn = "Etchmiadzin Cathedral in Vagharshapat is the mother church of Armenia and, by tradition, the oldest cathedral in the world still standing. It was founded around 301–303 by Gregory the Illuminator after king Trdat III adopted Christianity — making Armenia the first Christian state. The name means 'the Only-Begotten descended': in a vision, Christ showed Gregory the spot where the church should rise, striking the pagan temple beneath it with a golden hammer. The original building was rebuilt in cross-shaped form in 483 and renewed many times; the bell towers were added in the 17th century. Within its walls are the museum of the Catholicosate, where the Spear of Geghard and relics of Noah's Ark are shown, and the khachkars of ancient masters. Around the cathedral spread the palace of the Catholicos, theological seminary and gates. Every Armenian church worldwide traces its spiritual line to this place.",
        bodyRu = "Собор Эчмиадзин в Вагаршапате — материнская церковь Армении и, по преданию, древнейший из соборов мира, стоящий доныне. Он основан около 301–303 годов Григорием Просветителем после того, как царь Трдат III принял христианство, — Армения стала первым христианским государством. Имя значит «сошёл Единородный»: в видении Христос указал Григорию место для церкви, ударив золотым молотом по стоявшему внизу языческому храму. Первоначальное здание перестроили в крестообразное в 483 году и возобновляли многократно; колокольни добавлены в XVII веке. В стенах собора — музей Католикосата, где выставлены копьё из Гегарда и частицы Ноева ковчега, и хачкары древних мастеров. Вокруг раскинулись дворец Католикоса, духовная семинария и врата. Каждая армянская церковь мира возводит свою духовную линию к этому месту.",
        bodyHy = "Վաղարշապատի Էջմիածնի տաճարը Հայաստանի մայր եկեղեցին է և, ավանդության համաձայն, աշխարհի ամենահին կանգուն տաճարը։ Այն հիմնադրվել է մոտ 301–303 թվականներին Գրիգոր Լուսավորչի կողմից՝ Տրդատ Գ թագավորի քրիստոնեություն ընդունելուց հետո, երբ Հայաստանը դարձավ առաջին քրիստոնյա պետությունը։ Անունը նշանակում է «իջավ Միածինը». տեսիլքում Քրիստոսը Գրիգորին ցույց տվեց եկեղեցու տեղը՝ ոսկե մուրճով հարվածելով նրա տակ գտնվող հեթանոսական տաճարին։ Սկզբնական շենքը խաչաձև վերակառուցվեց 483 թվականին և բազմիցս նորոգվել. զանգակատներն ավելացվել են 17-րդ դարում։ Տաճարի պատերում է Կաթողիկոսության թանգարանը, որտեղ ցուցադրվում են Գեղարդի նիզակը և Նոյան տապանի մասունքները, ինչպես նաև հին վարպետների խաչքարերը։ Տաճարի շուրջ տարածվում են Կաթողիկոսի պալատը, հոգևոր ճեմարանը և դարպասները։ Աշխարհի ամենայն հայկական եկեղեցին իր հոգևոր գիծը բերում է այս վայրից։"
    ),
    WikiSeedArticle(
        id = "amberd", category = "fortresses", sortOrder = 105, section = "ancient",
        titleEn = "Amberd Fortress", titleRu = "Крепость Амберд", titleHy = "Ամբերդ ամրոց",
        bodyEn = "Amberd — 'the fortress in the clouds' — stands at 2,300 metres on a spur of Mount Aragats, where two mountain streams close a triangular cape. A fortress existed here by the 7th century; the preserved walls and bath belong to the 10th–13th centuries, when Amberd was a stronghold of the Pahlavuni princes and then of the Zakarians. The citadel of black basalt, the three-aisled church of 1026 and the bath with domed hall and clay pipes make up one of the most complete medieval castle complexes of Armenia. In 1236 the Mongols took and wrecked Amberd; a century later Timur's raids ended its life for good — and preserved it from later rebuilding. The road up from the Ararat plain through Byurakan is a climb through volcanic highland; the site, restored by Nicholas Toumanoff's campaigns of the 1960s, rewards the traveller with views over the entire Ararat valley.",
        bodyRu = "Амберд — «крепость в облаках» — стоит на высоте 2300 метров на отроге горы Арагац, там, где два горных ручья замыкают треугольный мыс. Крепость существовала здесь уже к VII веку; сохранившиеся стены и баня принадлежат к X–XIII векам, когда Амберд был оплотом князей Пахлавуни, а затем Закарянов. Цитадель из чёрного базальта, трёхнефная церковь 1026 года и баня с купольным залом и глиняными трубами составляют один из самых полных средневековых замковых комплексов Армении. В 1236 году монголы взяли и разорили Амберд; век спустя набеги Тимура окончательно погасили его жизнь — и сохранили от поздних перестроек. Дорога вверх от Араратской равнины через Бюракана — подъём сквозь вулканическое нагорье; комплекс, восстановленный экспедициями Николаса Туманова в 1960-х, вознаграждает путника видом на всю Араратскую долину.",
        bodyHy = "Ամբերդը՝ «ամպերի ամրոցը», կանգնած է ծովի մակարդակից 2300 մետր բարձրության վրա՝ Արագած լեռան լանջին, այնտեղ, որտեղ երկու լեռնային առվակ փակում են եռանկյուն հրվանդանը։ Ամրոց այստեղ եղել է դեռ 7-րդ դարում. պահպանված պարիսպներն ու բաղնիքը պատկանում են 10–13-րդ դարերին, երբ Ամբերդը Պահլավունի իշխանների, ապա Զաքարյանների հենակետն էր։ Սև բազալտից բերդը, 1026 թվականի եռանավ եկեղեցին և գմբեթավոր դահլիճով, կավե խողովակներով բաղնիքը կազմում են Հայաստանի ամենաամբողջական միջնադարյան ամրոցային համալիրներից մեկը։ 1236 թվականին մոնղոլները գրավեցին և ավերեցին Ամբերդը, իսկ դար անց Լենկթեմուրի արշավանքները վերջնականապես մարեցրին նրա կյանքը՝ միաժամանակ պահպանելով ուշ վերակառուցումներից։ Արարատյան դաշտից Բյուրականով դեպի վեր տանող ճանապարհը բարձրացում է հրաբխային լեռնաշխարհով. 1960-ականների Նիկոլաս Թումանովի արշավախմբերի վերականգնած համալիրը ճանապարհորդին պարգևում է ամբողջ Արարատյան դաշտի տեսարան։"
    ),
    WikiSeedArticle(
        id = "ani", category = "fortresses", sortOrder = 106, section = "ancient",
        titleEn = "Ani, city of 1001 churches", titleRu = "Ани — город 1001 церкви", titleHy = "Անի՝ 1001 եկեղեցու քաղաք",
        bodyEn = "Ani on the Akhurian river was the capital of the Bagratid kingdom and one of the great cities of the medieval world. At its peak in the 11th century it counted perhaps a hundred thousand people, rivalled only by Constantinople, Cairo and Baghdad, and its thousand and one churches earned it the name 'city of churches'. The walls of king Smbat II — double lines with round towers — still run for kilometres along the gorge. The cathedral by Trdat the architect (989–1001) rose on arches that shrugged off earthquakes for a millennium; the church of St Gregory of Tigran Honents (1215) keeps frescoes glowing with life; the round church of the Abughamrents and the cliff-side caves complete the city. Trade routes from China to Europe crossed at Ani. Its fall came in stages — Byzantium in 1045, the Seljuks, the Mongols, the earthquake of 1319 — until the city emptied and grass grew in its streets. Today the ruins straddle the closed Turkish-Armenian border, a UNESCO site and a silent monument to the Armenian Middle Ages.",
        bodyRu = "Ани на реке Ахурян был столицей Багратидского царства и одним из великих городов средневекового мира. В зените XI века здесь жило, возможно, сто тысяч человек — больше сравнимы лишь Константинополь, Каир и Багдад, а тысяча и одна церковь дала городу имя «город церквей». Стены царя Смбата II — двойные линии с круглыми башнями — до сих пор тянутся километрами вдоль ущелья. Собор архитектора Трдата (989–1001) встал на арках, переживавших землетрясения тысячелетие; церковь Святого Григория Тиграна Хоненца (1215) хранит фрески, дышащие жизнью; круглая церковь Абугамренц и пещеры на обрыве завершают город. В Ани пересекались торговые пути от Китая до Европы. Падение шло этапами — Византия в 1045-м, сельджуки, монголы, землетрясение 1319 года, — пока город не опустел и в его улицах не выросла трава. Сегодня руины стоят на закрытой турецко-армянской границе — объект ЮНЕСКО и безмолвный памятник армянскому Средневековью.",
        bodyHy = "Ախուրյան գետի վրա գտնվող Անին Բագրատունիների թագավորության մայրաքաղաքն էր և միջնադարյան աշխարհի մեծ քաղաքներից մեկը։ 11-րդ դարի իր բարձրակետում այստեղ, հավանաբար, ապրում էր հարյուր հազար մարդ. նրա հետ համեմատելի էին միայն Կոստանդնուպոլիսը, Կահիրեն և Բաղդադը, իսկ հազար ու մեկ եկեղեցին քաղաքին տվել է «եկեղեցիների քաղաք» անունը։ Սմբատ Բ թագավորի պարիսպները՝ կլոր աշտարակներով կրկնակի գծերը, մինչ օրս ձգվում են կիլոմետրերով կիրճի երկայնքով։ ճարտարապետ Տրդատի տաճարը (989–1001) բարձրացավ կամարների վրա, որոնք հազարամյակ դիմացան երկրաշարժերին. Տիգրան Հոնենցի Սուրբ Գրիգոր եկեղեցին (1215) պահում է կյանքով շնչող որմնանկարներ, իսկ Աբուղամրենցի կլոր եկեղեցին ու ժայռի քարանձավները լրացնում են քաղաքը։ Անիում հատվում էին Չինաստանից Եվրոպա տանող առևտրային ուղիները։ Անկումը փուլ առ փուլ եկավ. Բյուզանդիան 1045-ին, սելջուկները, մոնղոլները, 1319 թվականի երկրաշարժը, մինչև քաղաքը դատարկվեց և նրա փողոցներում խոտ աճեց։ Այսօր ավերակները կանգնած են փակ թուրք-հայկական սահմանի վրա՝ ՅՈՒՆԵՍԿՕ-ի հուշարձան և հայ միջնադարի լուռ վկայություն։"
    ),
    WikiSeedArticle(
        id = "artashes1", category = "kings", sortOrder = 107, section = "ancient",
        titleEn = "Artaxias I (Artashes)", titleRu = "Арташес I", titleHy = "Արտաշես Ա",
        bodyEn = "Artaxias I (ruled 189–160 BC) turned a satrapy on the ruins of the Seleucid power into the independent kingdom of Greater Armenia. A former general of Antiochus the Great, he declared himself king after the Roman defeat of the Seleucids at Magnesia, and Rome marked him 'king of the Armenians' in the Treaty of Apamea. He expanded the realm across the Ararat plain and, tradition says, invited Hannibal the Carthaginian to lay out his new capital, Artashat — 'the joy of Artashes' — on twelve hills at the confluence of the Araxes and Metsamor. Greek sources call him a lawgiver; boundary stones with Aramaic inscriptions 'King Artashes' still surface in the Ararat valley. Movses Khorenatsi wove him into legend as the wise ruler of a golden age. His dynasty, the Artaxiads, ruled for nearly two centuries and set the frontiers and the idea of Armenian statehood for all that followed.",
        bodyRu = "Арташес I (правил в 189–160 гг. до н. э.) превратил сатрапию на обломках державы Селевкидов в независимое царство Великой Армении. Бывший полководец Антиоха Великого, он объявил себя царём после того, как римляне разбили Селевкидов при Магнесии, а по Апамейскому договору Рим признал его «царём армян». Он расширил пределы царства по Араратской равнине и, по преданию, пригласил карфагенянина Ганнибала размечать новую столицу — Арташат, «радость Арташеса», — на двенадцати холмах у слияния Аракса и Мецамора. Греческие источники зовут его законодателем; пограничные камни с арамейской надписью «Царь Арташес» до сих пор выходят на поверхность в Араратской долине. Мовсес Хоренаци вплёл его в легенду как мудрого правителя золотого века. Его династия, Арташесяны, правила почти два века и задала границы и саму идею армянской государственности для всех последующих.",
        bodyHy = "Արտաշես Ա-ն (մ.թ.ա. 189–160) Սելևկյան տերության ավերակների վրա սատրապությունից վերածեց անկախ Մեծ Հայաստանի թագավորության։ Անտիոքոս Մեծի նախկին զորավարը ինքն իրեն թագավոր հռչակեց հռոմեացիների՝ Մագնեսիայում սելևկյաններին հաղթելուց հետո, իսկ Ապամեայի պայմանագրով Հռոմը նրան ճանաչեց «հայոց արքա»։ Նա ընդարձակեց թագավորությունը Արարատյան դաշտով և, ավանդության համաձայն, կարթագենացի Հաննիբալին հրավիրեց նոր մայրաքաղաքը՝ Արտաշատը, «Արտաշեսի ուրախությունը», հատակագծելու տասներկու բլուրների վրա՝ Արաքսի և Մեծամորի խառնարանի մոտ։ Հունական աղբյուրները նրան օրենսդիր են կոչում. «Արտաշես արքա» արամեերեն արձանագրությամբ սահմանաքարեր մինչ օրս դուրս են գալիս Արարատյան դաշտում։ Մովսես Խորենացին նրան հյուսել է լեգենդի մեջ՝ որպես ոսկեդարի իմաստուն գահակալ։ Նրա դինաստիան՝ Արտաշեսյանները, իշխեց գրեթե երկու դար և սահմանեց սահմաններն ու հայոց պետականության գաղափարը հետագա բոլորի համար։"
    ),
    WikiSeedArticle(
        id = "tigranes2", category = "kings", sortOrder = 108, section = "ancient",
        titleEn = "Tigranes the Great", titleRu = "Тигран II Великий", titleHy = "Տիգրան Բ Մեծ",
        bodyEn = "Tigranes II (ruled 95–55 BC) raised Armenia to an empire — the only time it stood among the first powers of the world. He had grown up as a hostage at the Parthian court and bought his crown with 'seventy valleys'; once king, he took back the valleys, annexed Sophene, subdued Media Atropatene and Syria, and married Cleopatra of Pontus. He struck coins with the tiara of the 'king of kings' and built a new capital, Tigranocerta, peopling it with settlers moved from Cappadocia. The Armenian state ran from the Caspian to the Mediterranean and to the sources of the Tigris. But the new power of Rome collided with him: Lucullus took Tigranocerta in 69 BC, and at Artaxat in 66 Pompey left Tigranes his crown as Rome's ally — for a tribute. He abdicated in old age in favour of his son and died at 85, having seen both the summit and the slope. His name remains the measure of Armenian greatness: 'Tigran the Great'.",
        bodyRu = "Тигран II (правил в 95–55 гг. до н. э.) поднял Армению до империи — единственный раз, когда она стояла в ряду первых держав мира. Юношей он был заложником при парфянском дворе и выкупил корону «семьюдесятью долинами»; став царём, вернул долины, присоединил Софену, покорил Мидию Атропатену и Сирию, женился на Клеопатре Понтийской. Он чеканил монеты с тиарой «царя царей» и построил новую столицу — Тигранакерт, населив её переселенцами из Каппадокии. Армянское государство простиралось от Каспия до Средиземного моря и до истоков Тигра. Но с ним столкнулась новая сила — Рим: в 69 году до н. э. Лукулл взял Тигранакерт, а в 66-м при Арташате Помпей оставил Тиграну корону как союзнику Рима — за дань. В старости он отрёкся в пользу сына и умер в 85 лет, увидев и вершину, и склон. Его имя остаётся мерилом армянского величия — «Тигран Великий».",
        bodyHy = "Տիգրան Բ-ն (մ.թ.ա. 95–55) Հայաստանը բարձրացրեց կայսրության աստիճանի՝ միակ անգամը, երբ այն կանգնած էր աշխարհի առաջին տերությունների շարքում։ Պատանի հասակում պատանդ էր պարթև արքունիքում և գահը փրկագնեց «յոթանասուն ձորերով». գահ բարձրանալով՝ հետ վերցրեց ձորերը, միացրեց Ծոփքը, ենթարկեց Ատրպատականը և Սիրիան, ամուսնացավ Պոնտացի Կլեոպատրայի հետ։ Նա հատում էր «արքայից արքա» տիարով դրամներ և կառուցեց նոր մայրաքաղաք՝ Տիգրանակերտը՝ բնակեցնելով այն Կապադովկիայից տեղափոխվածներով։ Հայոց պետությունը ձգվում էր Կասպիցից մինչև Միջերկրական և Տիգրիսի ակունքները։ Բայց նրա հետ բախվեց Հռոմի նոր հզորությունը. մ.թ.ա. 69-ին Լուկուլլոսը վերցրեց Տիգրանակերտը, իսկ 66-ին Արտաշատում Պոմպեոսը Տիգրանին թողեց թագը՝ որպես Հռոմի դաշնակցի՝ տուրքի դիմաց։ Ծեր հասակում նա գահը զիջեց որդուն և մահացավ 85 տարեկանում՝ տեսած և՛ գագաթը, և՛ լանջը։ Նրա անունը մնում է հայոց մեծության չափանիշը՝ «Տիգրան Մեծ»։"
    ),
    WikiSeedArticle(
        id = "trdat3", category = "kings", sortOrder = 109, section = "ancient",
        titleEn = "Trdat III the Great", titleRu = "Трдат III Великий", titleHy = "Տրդատ Գ Մեծ",
        bodyEn = "Trdat III (ruled 287–330) is the king who made Armenia the first Christian state in the world. Raised as a hostage in Rome, he fought his way back to the throne with Roman help and defeated the Sasanians, earning from the legend of Diocletian the honour of a Roman ally. The same tradition tells that he martyred the virgins Hripsime and Gayane and went mad — until Gregory, imprisoned for thirteen years in Khor Virap, was brought out to heal him. In 301 Trdat was baptised by Gregory and proclaimed Christianity the state religion, a dozen years before Constantine's edict. He then helped build the first Etchmiadzin cathedral at the place of Gregory's vision. Late in life the king abdicated, retired as a monk to Cappadocia and was later canonised by the Armenian Church. With him the pagan age of Armenia closes and the age of the cross begins.",
        bodyRu = "Трдат III (правил в 287–330) — царь, сделавший Армению первым христианским государством мира. Воспитанный заложником в Риме, он с римской помощью пробился обратно на трон и разбил Сасанидов, заслужив честь римского союзника. Та же традиция рассказывает, что он предал мученической смерти дев Рипсиме и Гаяне и впал в безумие — пока из Хор Вирапа, где тот томился тринадцать лет, не вывели Григория, чтобы исцелить царя. В 301 году Трдат принял крещение от Григория и провозгласил христианство государственной религией — на дюжину лет раньше эдикта Константина. Затем он помог строить первый собор Эчмиадзина на месте видения Григория. В конце жизни царь отрёкся, ушёл монахом в Каппадокию и позднее был канонизирован Армянской церковью. С ним языческий век Армении закрывается и начинается век креста.",
        bodyHy = "Տրդատ Գ-ն (287–330) այն թագավորն է, որը Հայաստանը դարձրեց աշխարհի առաջին քրիստոնյա պետությունը։ Հռոմում պատանդ մեծացած՝ նա հռոմեական օգնությամբ վերադարձավ գահին և պարտության մատնեց սասանյաններին՝ վաստակելով Հռոմի դաշնակցի կոչումը։ Նույն ավանդությունը պատմում է, որ նա նահատակեց Հռիփսիմե և Գայանե կույսերին ու խելագարվեց, մինչև Խոր Վիրապից՝ որտեղ նա տասներեք տարի տանջվում էր, դուրս բերեցին Գրիգորին՝ արքային բժշկելու համար։ 301 թվականին Տրդատ մկրտվեց Գրիգորի ձեռքով և քրիստոնեությունը հռչակեց պետական կրոն՝ Կոստանդիանոսի հրովարտակից մեկ տասնյակ տարի առաջ։ Ապա նա օգնեց կառուցել Էջմիածնի առաջին տաճարը՝ Գրիգորի տեսիլքի վայրում։ Կյանքի վերջում արքան հրաժարվեց գահից, ճգնեց Կապադովկիայում և հետագայում սրբացվեց Հայ եկեղեցու կողմից։ Նրա հետ փակվում է Հայաստանի հեթանոսական դարը և բացվում խաչի դարը։"
    ),
    WikiSeedArticle(
        id = "mashtots", category = "culture", sortOrder = 110, section = "ancient",
        titleEn = "Mesrop Mashtots and the alphabet", titleRu = "Месроп Маштоц и алфавит", titleHy = "Մեսրոպ Մաշտոցը և այբուբենը",
        bodyEn = "In 405 AD the monk and scholar Mesrop Mashtots created the Armenian alphabet — thirty-six letters ordered by sound, not borrowed but designed, each letter a small work of calligraphic logic. Until then Armenian had been written in Greek, Aramaic or Syriac scripts that could not carry its sounds. Mashtots and his pupils opened schools across the country and launched the great age of translation: the Bible, the Greek fathers, chronicles, law and science were rendered into Armenian within a few generations, some works surviving only in Armenian. The alphabet became the vessel of identity through the centuries when the state was gone: language kept the nation, the church kept the language, the letters kept both. Mashtots died in 440 and is buried at Oshakan, a place of pilgrimage to this day. His statue with the open alphabet stands at the entrance of the Matenadaran manuscript museum in Yerevan.",
        bodyRu = "В 405 году монах и учёный Месроп Маштоц создал армянский алфавит — тридцать шесть букв, выстроенных по звучанию, не заимствованных, а спроектированных, каждая буква — маленькое творение каллиграфической логики. До того армянский записывали греческими, арамейскими или сирийскими письменами, не передававшими его звуков. Маштоц с учениками открыл школы по всей стране и начал великий век перевода: Библия, греческие отцы, хроники, право и наука за несколько поколений были переложены на армянский, иные сочинения сохранились только в армянском. Алфавит стал ковчегом идентичности в века, когда государства не было: язык хранил нацию, церковь хранила язык, буквы хранили и то и другое. Маштоц умер в 440 году и погребён в Ошакане — месте паломничества по сей день. Его статуя с раскрытым алфавитом стоит у входа в матенадаран — музей рукописей Еревана.",
        bodyHy = "405 թվականին վանական և գիտնական Մեսրոպ Մաշտոցը ստեղծեց հայոց այբուբենը՝ երեսունվեց տառ, դասավորված ըստ հնչյունների, ոչ թե փոխառված, այլ նախագծված. յուրաքանչյուր տառ ձեռագրական տրամաբանության փոքրիկ ստեղծագործություն է։ Մինչ այդ հայերենը գրում էին հունարեն, արամեերեն կամ ասորերեն գրերով, որոնք չէին փոխանցում նրա հնչյունները։ Մաշտոցն ու աշակերտները երկրով մեկ դպրոցներ բացեցին և սկսեցին թարգմանության մեծ դարը. Աստվածաշունչը, հունարեն հայրերը, տարեգրությունները, իրավունքն ու գիտությունը մի քանի սերնդի ընթացքում հայերեն են թարգմանվել, իսկ որոշ երկեր պահպանվել են միայն հայերեն։ Այբուբենը դարձավ ինքնության տապանան այն դարերի ընթացքում, երբ պետություն չկար. լեզուն պահում էր ազգին, եկեղեցին՝ լեզուն, տառերը՝ երկուսին էլ։ Մաշտոցը մահացավ 440 թվականին և թաղված է Օշականում՝ մինչ օրս ուխտատեղի։ Բաց այբուբենով նրա արձանը կանգնած է Երևանի Մատենադարանի մուտքի մոտ։"
    ),
    WikiSeedArticle(
        id = "khorenatsi", category = "culture", sortOrder = 111, section = "ancient",
        titleEn = "Movses Khorenatsi", titleRu = "Мовсес Хоренаци", titleHy = "Մովսես Խորենացի",
        bodyEn = "Movses Khorenatsi — 'Moses of Khoren' — lived in the 5th century, the golden age of Armenian letters, and wrote the 'History of Armenia', the first full history of the nation from its origins to his own day. He gathered oral tradition, songs, genealogies, Greek and Syriac sources and shaped them into a narrative peopled by patriarchs, kings and prophets of the land. His account of Haik the archer defying Bel, of king Artashes legislating on hills, gave Armenians a memory as old as their neighbours'. Later scholarship debates his dates and sources, but his place in the culture is beyond debate: he is 'the father of Armenian history'. His book became the school of historiography for centuries of Armenian writers. The highest prize of Armenian humanities today carries his name, and his statue sits by the Matenadaran among the giants of the national mind.",
        bodyRu = "Мовсес Хоренаци — «Моисей Хоренский» — жил в V веке, в золотой век армянской письменности, и написал «Историю Армении», первую полную историю народа от его истоков до собственных дней. Он собрал устное предание, песни, родословия, греческие и сирийские источники и сплавил их в повествование, населенное праотцами, царями и пророками земли. Его рассказ о стреляющем из лука Айке, бросившем вызов Бэлу, о царе Арташесе, законодательствующем с холмов, дал армянам память, древнюю, как у соседей. Позднейшая наука спорит о его датах и источниках, но его место в культуре бесспорно — он «отец армянской истории». Его книга стала школой историописания для поколений армянских авторов. Высшая награда армянской гуманитарной науки носит сегодня его имя, а его статуя сидит у Матенадарана среди гигантов национальной мысли.",
        bodyHy = "Մովսես Խորենացին ապրել է 5-րդ դարում՝ հայ գրականության ոսկեդարում, և գրել է «Հայոց պատմությունը»՝ ազգի առաջին ամբողջական պատմությունը իր սկզբից մինչև իր օրերը։ Նա հավաքել է բանավոր ավանդությունը, երգերը, ծագումնաբանությունները, հունական և ասորական աղբյուրները և դրանք ձուլել մի պատմվածքի մեջ, բնակեցված երկրի նախահայրերով, արքաներով ու մարգարեներով։ Աղեղնավոր Հայկի՝ Բելին դիմագրավելու, Արտաշես արքայի՝ բլուրներից օրենք դնելու պատմությունը հայոց հիշողությունը դարձրեց հարևանների հիշողության պես հին։ Ուշ գիտությունը վիճում է նրա թվագրությունների և աղբյուրների շուրջ, բայց նրա տեղը մշակույթում անվիճելի է. նա «հայ պատմագրության հայրն» է։ Նրա գիրքը դարձավ պատմագրության դպրոց հայ հեղինակների սերունդների համար։ Հայ հումանիտար գիտության բարձրագույն մրցանակն այսօր կրում է նրա անունը, իսկ արձանը նստած է Մատենադարանի մոտ՝ ազգային մտքի հսկաների շարքում։"
    ),
    WikiSeedArticle(
        id = "christianity", category = "history", sortOrder = 112, section = "ancient",
        titleEn = "The adoption of Christianity (301)", titleRu = "Принятие христианства (301)", titleHy = "Քրիստոնեության ընդունումը (301)",
        bodyEn = "In 301 AD Armenia became the first country to adopt Christianity as its state religion — before the Edict of Milan, before Constantine's own baptism. The story holds that king Trdat III, after persecuting the faith and falling ill, was healed by Gregory, a nobleman he had kept thirteen years in the pit of Khor Virap. Gregory baptised the king, and the court followed; pagan temples gave way to the first churches. Etchmiadzin — 'the Only-Begotten descended' — rose at the site of Gregory's vision, and the new faith wove itself into Armenian identity so deeply that church and nation became one word in times to come. The conversion reordered the calendar of the land: the age of martyrs Hripsime and Gayane, the line of Catholicoses, the schools of Mashtots all begin here. For a country on the frontier of empires, Christianity became the inner fortress that no conquest could take.",
        bodyRu = "В 301 году Армения стала первой страной, принявшей христианство как государственную религию — раньше Миланского эдикта, раньше крещения самого Константина. Предание гласит, что царь Трдат III, гонавший веру и впавший в болезнь, был исцелён Григорием — вельможей, которого тринадцать лет держал в яме Хор Вирапа. Григорий крестил царя, за ним пошёл двор; языческие храмы уступали место первым церквям. Эчмиадзин — «сошёл Единородный» — встал на месте видения Григория, а новая вера вплелась в армянскую идентичность так глубоко, что церковь и народ в грядущие века стали одним словом. Обращение пересоздало календарь земли: век мучениц Рипсиме и Гаяне, линия Католикосов, школы Маштоца — всё начинается здесь. Для страны на границе империй христианство стало внутренней крепостью, которую не мог взять ни один завоеватель.",
        bodyHy = "301 թվականին Հայաստանը դարձավ առաջին երկիրը, որն ընդունեց քրիստոնեությունը որպես պետական կրոն՝ Միլանի հրովարտակից և Կոստանդիանոսի մկրտությունից առաջ։ Ավանդությունը պատմում է, որ Տրդատ Գ թագավորը, հալածելով հավատը և հիվանդանալով, բժշկվեց Գրիգորի՝ այն իշխանի ձեռքով, ում տասներեք տարի պահում էր Խոր Վիրապի փոսում։ Գրիգորը մկրտեց արքային, նրա ետևից գնաց արքունիքը, հեթանոսական տաճարները տեղը զիջեցին առաջին եկեղեցիներին։ Էջմիածինը՝ «Միածնի իջնելու վայրը», բարձրացավ Գրիգորի տեսիլքի տեղում, իսկ նոր հավատն այնքան խոր նյութվեց հայկական ինքնության մեջ, որ եկեղեցին ու ժողովուրդը գալիք դարերում դարձան մեկ բառ։ Դարձը վերաստեղծեց երկրի օրացույցը. Հռիփսիմե և Գայանե նահատակների դարը, կաթողիկոսների գիծը, Մաշտոցի դպրոցները՝ ամեն ինչ սկսվում է այստեղ։ Կայսրությունների սահմանին կանգնած երկրի համար քրիստոնեությունը դարձավ ներքին բերդ, որը ոչ մի նվաճում չէր կարող վերցնել։"
    ),
    WikiSeedArticle(
        id = "cilicia", category = "history", sortOrder = 113, section = "ancient",
        titleEn = "The Armenian Kingdom of Cilicia", titleRu = "Киликийское армянское царство", titleHy = "Կիլիկյան հայկական թագավորությունը",
        bodyEn = "When the Seljuk advance pushed Armenians west in the 11th century, a new Armenia grew on the Mediterranean coast in Cilicia — between the Taurus mountains and the sea. The Rubenid dynasty, from the royal Bagratid line, built a state of fortresses (Sis, Anazarba, Korykos) and harbour towns that lived by trade with Genoa, Venice and the Crusader states. Levon I the Magnificent was crowned king in 1198 with a crown blessed by both the Pope and the Byzantine emperor, and his court shone with chivalry, law codes and the pen of the historian Smbat Sparapet. Cilician Armenians stood with the Crusaders and carried the culture of the homeland into a Mediterranean key: manuscript painting, architecture, music. The kingdom outlived the Crusader states by a century, falling at last to the Mamluks in 1375; Levon V, the last king, died in Paris, and his crown passed to the kings of France. For three centuries the Armenian statehood lived by the sea — an epilogue that kept the idea of the nation alive until the modern age.",
        bodyRu = "Когда наступление сельджуков в XI веке толкнуло армян на запад, новая Армения выросла на средиземноморском берегу Киликии — между Таврскими горами и морем. Династия Рубенидов из царского рода Багратидов построила государство крепостей (Сис, Аназарба, Корикос) и портовых городов, живших торговлей с Генуей, Венецией и государствами крестоносцев. Левон I Великолепный короновался в 1198 году короной, освящённой и Папой, и византийским императором, а его двор сиял рыцарством, сводами законов и пером историка Смбата Гундстабла. Киликийские армяне стояли плечом к плечу с крестоносцами и переложили культуру родины на средиземноморский лад: книжная миниатюра, архитектура, музыка. Царство пережило государства крестоносцев на век, пав под ударами мамлюков в 1375 году; Левон V, последний царь, умер в Париже, его корона перешла к королям Франции. Три века армянская государственность жила у моря — эпилог, сохранивший идею нации до нового времени.",
        bodyHy = "Երբ սելջուկների առաջխաղացումը 11-րդ դարում հայերին հրեց դեպի արևմուտք, նոր Հայաստան աճեց Միջերկրականի ափին՝ Կիլիկիայում, Տավրոսի լեռների և ծովի միջև։ Ռուբենյանների դինաստիան՝ Բագրատունիների արքայական գծից, կառուցեց բերդերի (Սիս, Անարզաբա, Կոռիկոս) և նավահանգիստ քաղաքների պետություն, որն ապրում էր Ջենովայի, Վենետիկի և խաչակրաց պետությունների հետ առևտրով։ Լևոն Ա Մեծանունին թագադրվեց 1198 թվականին՝ և՛ Պապի, և՛ բյուզանդական կայսրի օրհնված թագով, իսկ նրա արքունիքը փայլում էր ասպազնությամբ, իրավունքի ժողովածուներով և պատմիչ Սմբատ Գունդստաբլի գրչով։ Կիլիկյան հայերը ուսի-ուսի կանգնած էին խաչակիրների հետ և հայրենիքի մշակույթը դասավորում էին միջերկրածովյան տոնայնությամբ. մանրանկարչություն, ճարտարապետություն, երաժշտություն։ Թագավորությունը խաչակրաց պետություններից ապրեց մեկ դար ավելի՝ վերջին անգամ ընկնելով մամլուկների ձեռքը 1375 թվականին. վերջին արքա Լևոն Ե-ն մահացավ Փարիզում, իսկ նրա թագը անցավ Ֆրանսիայի արքաներին։ Երեք դար հայոց պետականությունն ապրեց ծովի ափին՝ էպիլոգ, որ ազգի գաղափարը պահեց կենդանի մինչև նոր ժամանակներ։"
    ),
    WikiSeedArticle(
        id = "dvin", category = "fortresses", sortOrder = 114, section = "ancient",
        titleEn = "Dvin, the medieval capital", titleRu = "Двин — средневековая столица", titleHy = "Դվինը՝ միջնադարյան մայրաքաղաք",
        bodyEn = "Dvin, beside today's Hnaberd village south of Yerevan, was for six centuries the beating heart of Armenia — capital under the Arsacids, the marzpans, the Caliphate's emirs and the early Bagratids. Founded by king Khosrov III in the 4th century on an older Urartian site, it stood on trade roads linking Byzantium, Persia and the Arab world. At its peak it counted some 100,000 inhabitants: three markets, caravanserais, a palace of the Catholicos and the grand cathedral of Saint Gregory with its famed sculpture of king Smbat. Arab geographers called it 'the mother of Arminiya'. The city was ruined by earthquakes (892, 995) and the Seljuks, and excavation since 1937 has opened its citadel, the cathedral platform and the palace of the governors. Its carved lattices and lion figures are among the masterpieces of early medieval Armenian art.",
        bodyRu = "Двин, у нынешнего села Хнаберд к югу от Еревана, шесть веков был сердцем Армении — столицей при Аршакуни, марзпанах, эмирах халифата и ранних Багратидах. Основанный царём Хосровом III в IV веке на более древнем, урартском месте, он стоял на торговых путях, связывавших Византию, Персию и арабский мир. В зените здесь жило около ста тысяч человек: три рынка, караван-сараи, дворец Католикоса и великий собор Святого Григория со знаменитой скульптурной группой царя Смбата. Арабские географы звали его «матерью Арминии». Город добили землетрясения (892, 995) и сельджуки; раскопки с 1937 года открыли цитадель, плато собора и дворец правителей. Его резные решётки и фигуры львов — среди шедевров раннесредневекового армянского искусства.",
        bodyHy = "Դվինը՝ ներկայիս Հնաբերդ գյուղի մոտ, Երևանից հարավ, վեց դար Հայաստանի սիրտն էր. մայրաքաղաք Արշակունիների, մարզպանների, խալիֆայության էմիրների և վաղ Բագրատունիների օրոք։ Հիմնադրվելով Խոսրով Գ թագավորի կողմից 4-րդ դարում՝ ավելի հին, ուրարտական տեղանքում, այն կանգնած էր Բյուզանդիան, Պարսկաստանն ու արաբական աշխարհը կապող առևտրային ճանապարհների վրա։ Իր գագաթնակետում այստեղ ապրում էր շուրջ հարյուր հազար մարդ. երեք շուկա, քարավանատներ, Կաթողիկոսի պալատը և Սուրբ Գրիգոր մեծ տաճարը՝ Սմբատ թագավորի հռչակավոր քանդակով։ Արաբ աշխարհագրագետներն այն կոչում էին «Արմինիայի մայր»։ Քաղաքը կործանեցին երկրաշարժերը (892, 995) և սելջուկները. 1937 թվականից պեղումները բացել են բերդը, տաճարի հարթակը և իշխանների պալատը։ Դվինի քանդակազարդ վանդակաճաղերն ու առյուծների պատկերները վաղ միջնադարյան հայ արվեստի գլուխգործոցներից են։"
    ),
    WikiSeedArticle(
        id = "artashat", category = "fortresses", sortOrder = 115, section = "ancient",
        titleEn = "Artashat, city of Hannibal", titleRu = "Арташат — город Ганнибала", titleHy = "Արտաշատը՝ Հաննիբալի քաղաքը",
        bodyEn = "Artashat — 'the joy of Artashes' — was the capital of Greater Armenia for nearly five centuries, founded around 176 BC at the junction of the Araxes and Metsamor rivers. Tradition, recorded by Movses Khorenatsi and Plutarch, says the exiled Hannibal himself laid out the plan for king Artaxias I. The city stood on the silk road between Europe and Asia: Strabo mentions its theatre. Artashat kept its role under the Arsacids until sacked by Shapur II in 368–369; it revived beside Dvin in the early middle ages. Excavations since the 1970s uncover its walls, streets and a theatre carved into the hill — the Armenian Ephesus, as archaeologists call it.",
        bodyRu = "Арташат — «радость Арташеса» — почти пять веков был столицей Великой Армении: основан около 176 года до н. э. у слияния Аракса и Мецамора. Предание, записанное Мовсесом Хоренаци и Плутархом, говорит, что план для царя Арташеса I размечал сам изгнанный Ганнибал. Город стоял на шелковом пути между Европой и Азией; Страбон упоминает его театр. Арташат сохранял роль при Аршакуни до разгрома Шапуром II в 368–369 годах; возрождался рядом с Двином в раннем Средневековье. Раскопки с 1970-х открывают стены, улицы и врезанный в холм театр — «армянский Эфес», как зовут его археологи.",
        bodyHy = "Արտաշատը՝ «Արտաշեսի ուրախությունը», գրեթե հինգ դար Մեծ Հայաստանի մայրաքաղաքն էր. հիմնադրվել է մոտ մ.թ.ա. 176 թվականին Արաքսի և Մեծամորի խառնարանի մոտ։ Մովսես Խորենացու և Պլուտարքոսի հիշատակած ավանդությունն ասում է, որ Արտաշես Ա թագավորի համար քաղաքի հատակագիծը գծել է ինքը՝ աքսորյալ Հաննիբալը։ Քաղաքը կանգնած էր Եվրոպան և Ասիան կապող մետաքսի ճանապարհին. Ստրաբոնը հիշատակում է նրա թատրոնը։ Արտաշատը պահպանեց իր դերը Արշակունիների օրոք մինչև Շապուհ Բ-ի ավերը (368–369), ապա վերակենդանացավ Դվինի կողքին վաղ միջնադարում։ 1970-ականներից պեղումները բացում են պարիսպները, փողոցները և բլրի մեջ փորված թատրոնը, որ հնագետներն անվանում են «հայկական Էֆեսոս»։"
    ),
    WikiSeedArticle(
        id = "tigranakert", category = "fortresses", sortOrder = 116, section = "ancient",
        titleEn = "Tigranocerta, the lost capital", titleRu = "Тигранакерт — потерянная столица", titleHy = "Տիգրանակերտը՝ կորսված մայրաքաղաքը",
        bodyEn = "Tigranocerta was the capital Tigranes the Great raised around 80 BC in the south-west of his empire, on the river Nicephorius, to overshadow the old centers. Twelve Greek cities of Cappadocia and Cilicia were moved wholesale to people it; walls of 25 metres height embraced theatres and parks. Lucullus took it in 69 BC after the battle of the same name; the transferred Greeks opened the gates, and the city's treasure fed Rome. Tigranes later rebuilt it, but the site — near modern Silvan in Turkey — never regained its glory. A different, later Tigranakert, founded in Artsakh, has been excavated since 2005 and is one of the best-preserved Armenian cities of the antique periphery. The name itself became a byword for a king's ambition and its price.",
        bodyRu = "Тигранакерт — столица, которую Тигран Великий заложил около 80 года до н. э. на юго-западе империи, на реке Никефорий, чтобы затмить старые центры. Двенадцать греческих городов Каппадокии и Киликии переселили сюда целиком, чтобы населить его; стены высотой в 25 метров охватывали театры и парки. Лукулл взял его в 69 году до н. э. после одноимённой битвы: переселённые греки открыли ворота, а сокровища города накормили Рим. Тигран позже отстроил столицу, но место — у нынешнего Сильвана в Турции — более не вернуло величия. Другой, позднейший Тигранакерт, основанный в Арцахе, раскапывается с 2005 года и остаётся одним из лучших по сохранности армянских городов античной периферии. Само имя стало нарицательным для царской амбиции и её цены.",
        bodyHy = "Տիգրանակերտը այն մայրաքաղաքն է, որ Տիգրան Մեծը հիմնեց մոտ մ.թ.ա. 80 թվականին կայսրության հարավ-արևմուտքում՝ Նիկեփորիոս գետի վրա, հին կենտրոններին ստվերելու համար։ Բնակեցնելու նպատակով այստեղ ամբողջովին տեղափոխվեցին Կապադովկիայի և Կիլիկիայի տասներկու հունական քաղաքներ. 25 մետր բարձրության պարիսպները պարփակում էին թատրոններ ու պուրակներ։ Լուկուլլոսը վերցրեց այն մ.թ.ա. 69 թվականին համանուն ճակատամարտից հետո. տեղահանված հույները բացեցին դարպասները, իսկ քաղաքի գանձը կերակրեց Հռոմը։ Տիգրանը հետագայում վերակառուցեց այն, բայց վայրը՝ ներկայիս Սիլվանի մոտ Թուրքիայում, երբեք չվերագտավ իր փառքը։ Մեկ այլ՝ ուշ շրջանի Տիգրանակերտ, որ հիմնվել է Արցախում, պեղվում է 2005 թվականից և հնագույն ծայրագավառի լավ պահպանված հայկական քաղաքներից է։ Իր անունն ինքը դարձավ թագավորական հավակնոտության և դրա գնի հոմանիշ։"
    ),
    WikiSeedArticle(
        id = "tatev", category = "fortresses", sortOrder = 117, section = "ancient",
        titleEn = "Tatev Monastery", titleRu = "Монастырь Татев", titleHy = "Տաթևի վանք",
        bodyEn = "Tatev crowns a plateau above the Vorotan gorge in Syunik, at the edge of a basalt tongue that seems to float over the canyon. From 895 it was the seat of a famous monastery school; in the 14th century its university carried Armenian philosophy and miniature through the darkest decades, led by Grigor Tatevatsi, whose chair-stone stands in the yard. The church of Sts Paul and Peter (895–906) and the tomb-church of Grigor the Illuminator anchor the ensemble; Gavazan, the 'swaying column' of 904, tilted when earthquakes — or pranksters' horses — shook it, warning the brothers of danger. The name itself is legend: 'tat ev' — 'give the wings', the prayer of a builder. The Wings of Tatev, the longest reversible cableway in the world (5.7 km), now carries visitors across the gorge.",
        bodyRu = "Татев венчает плато над Воротанским ущельем в Сюнике, на краю базальтового языка, словно повисшего над каньоном. С 895 года здесь была знаменитая монастырская школа; в XIV веке университет Татева пронёс армянскую философию и миниатюру сквозь самые тёмные десятилетия под водительством Григора Татеваци, чей камень-трон стоит во дворе. Церковь Свв. Павла и Петра (895–906) и усыпальница Григория Просветителя замыкают ансамбль; Гавазан, «качающийся столп» 904 года, наклонялся при землетрясениях — или когда к нему подгоняли коней, — предупреждая братию об опасности. Само имя — легенда: «тат ев», «дай крылья» — молитва строителя. «Крылья Татева», самая длинная реверсивная канатная дорога мира (5,7 км), теперь несёт гостей через ущелье.",
        bodyHy = "Տաթևը թագադրում է Որոտանի կիրճի վրա բարձրացող սարահարթը Սյունիքում՝ բազալտե լեզվակի եզրին, որ կարծես լողում է կիրճի վրայով։ 895 թվականից այստեղ հռչակավոր վանական դպրոց էր. 14-րդ դարում Տաթևի համալսարանը Գրիգոր Տաթևացու գլխավորությամբ հայ փիլիսոփայությունն ու մանրանկարչությունը տարավ ամենամռայլ տասնամյակների միջով. նրա աթոռաքարը կանգնած է բակում։ Սուրբ Պողոս-Պետրոս եկեղեցին (895–906) և Գրիգոր Լուսավորչի գերեզմանաեկեղեցին ամրագրում են համալիրը. 904 թվականի Գավազանը՝ «տատանվող սյունը», խոնարհվում էր երկրաշարժերի կամ երբ նրան ձի էին մոտեցնում, վանականներին զգուշացնելով վտանգի մասին։ Իր անունն իսկ լեգենդ է. «թաթ և»՝ «թև տուր», շինողի աղոթքը։ «Տաթևի թևերը»՝ աշխարհի ամենաերկար երկկողմանի ճոպանուղին (5,7 կմ), այսօր հյուրերին տանում է կիրճի վրայով։"
    ),
    WikiSeedArticle(
        id = "noravank", category = "fortresses", sortOrder = 118, section = "ancient",
        titleEn = "Noravank", titleRu = "Нораванк", titleHy = "Նորավանք",
        bodyEn = "Noravank — 'new monastery' — hides in the red rocks of the Amaghu gorge, where cliffs close over the road and the light turns amber at sunset. It was the seat of the Orbelian princes and the studio of Momik, the architect and miniaturist who created here, around 1321, the two-storey church of Surb Astvatsatsin: a narrow stone stair joins the storeys, and the facade carries God the Father with the Spirit and the Crucifixion — unique in Armenian stone carving. The church of Surb Karapet (1221–1227) keeps khachkars by Momik and his teacher Siranes. The complex was restored in the 20th century after centuries of earthquakes and oblivion. Noravank pairs the severity of Armenian architecture with the drama of its landscape like no other site.",
        bodyRu = "Нораванк — «новый монастырь» — прячется в красных скалах ущелья Амагху, где обрывы сходятся над дорогой, а свет на закате становится янтарным. Он был резиденцией князей Орбелянов и мастерской Момика — архитектора и миниатюриста, создавшего здесь около 1321 года двухъярусную церковь Сурб Аствацацин: узкая каменная лестница соединяет ярусы, на фасаде — Бог Отец с Духом и Распятие — единственное в армянской камнерезке. Церковь Сурб Карапет (1221–1227) хранит хачкары Момика и его учителя Сиранеса. Комплекс восстановлен в XX веке после веков землетрясений и забвения. Нораванк сочетает строгость армянской архитектуры с драматизмом ландшафта, как ни одно другое место.",
        bodyHy = "Նորավանքը՝ «նոր վանքը», թաքնված է Ամաղուի կիրճի կարմիր ժայռերում, որտեղ ժայռերը փակվում են ճանապարհի վրա, իսկ մայրամուտին լույսը դառնում է սաթի գույն։ Այն Օրբելյան իշխանների նստավայրն էր և Մոմիկի արվեստանոցը՝ ճարտարապետի ու մանրանկարչի, որ այստեղ ստեղծեց մոտ 1321 թվականին երկհարկ Սուրբ Աստվածածին եկեղեցին. նեղ քարե աստիճանը միացնում է հարկերը, իսկ ճակատին՝ Հայր Աստվածը Հոգու և Խաչելության հետ, եզակի հայկական քանդակագործության մեջ։ Սուրբ Կարապետ եկեղեցին (1221–1227) պահում է Մոմիկի և նրա ուսուցիչ Սիրանեսի խաչքարերը։ Համալիրը վերականգնվել է 20-րդ դարում՝ երկրաշարժերի ու մոռացության դարերից հետո։ Նորավանքը հայ ճարտարապետության խստությունը համադրում է բնության դրամատիզմի հետ, ինչպես ոչ մի այլ վայր։"
    ),
    WikiSeedArticle(
        id = "haghpat", category = "fortresses", sortOrder = 119, section = "ancient",
        titleEn = "Haghpat Monastery", titleRu = "Монастырь Ахпат", titleHy = "Հաղպատի վանք",
        bodyEn = "Haghpat, founded in 976 on a high plateau of Lori above the Debed river, was the great scholarly house of the northern kingdom: its library and scriptorium copied and kept manuscripts through eight hundred years. The cathedral of Surb Nishan (976–991) shows the pure cross-dome style of the Bagratid age; the bell-tower of 1245, the book depository with its umbrella vault, and the refectory hall complete one of the most complete medieval ensembles of Armenia. Here taught Grigor Magistros, and the neighbouring school of Sanahin shares the same golden age. UNESCO listed Haghpat with Sanahin in 1996. The view over the Debed canyon makes the road itself a pilgrimage.",
        bodyRu = "Ахпат, основанный в 976 году на высоком плато Лори над рекой Дебед, был великой учёной обителью северного царства: его библиотека и скрипторий восемьсот лет переписывали и хранили рукописи. Собор Сурб Ншан (976–991) являет чистый крестово-купольный стиль багратидовской эпохи; колокольня 1245 года, книгохранилище со шатровым сводом и трапезный зал завершают один из самых полных средневековых ансамблей Армении. Здесь учил Григор Магистр, а с соседним Санаином Ахпат делит один золотой век. ЮНЕСКО внесло Ахпат вместе с Санаином в 1996 году. Вид на каньон Дебеда превращает в паломничество саму дорогу.",
        bodyHy = "Հաղպատը, հիմնված 976 թվականին Լորու բարձրադիր սարավանդի վրա՝ Դեբեդ գետի վրա, հյուսիսային թագավորության մեծ գիտակրոնական կենտրոնն էր. նրա մատենադարանն ու գրչատունը ութ հարյուր տարի ընդօրինակում և պահում էին ձեռագրեր։ Սուրբ Նշան տաճարը (976–991) մաքուր խաչագմբեթ ոճ է Բագրատունիների դարից. 1245 թվականի զանգակատունը, հովանոցաձև թաղով գրապահոցը և սեղանատունը լրացնում են Հայաստանի ամենաամբողջական միջնադարյան համալիրներից մեկը։ Այստեղ ուսուցանել է Գրիգոր Մագիստրոսը, իսկ հարևան Սանահինի հետ Հաղպատը կիսում է նույն ոսկեդարը։ ՅՈՒՆԵՍԿՕ-ն Հաղպատը Սանահինի հետ ցուցակագրեց 1996 թվականին։ Դեբեդի կիրճի տեսարանը իսկ ճանապարհը վերածում է ուխտի։"
    ),
    WikiSeedArticle(
        id = "sanahin", category = "fortresses", sortOrder = 120, section = "ancient",
        titleEn = "Sanahin Monastery", titleRu = "Монастырь Санаин", titleHy = "Սանահինի վանք",
        bodyEn = "Sanahin — 'this one is older than that', the folk etymology says, pointing at Haghpat across the valley — was founded in the 10th century on a Lori hillside and became a university before it was a fortress: its academy of Grigor Magistros taught humanities, theology and even calendar science. The churches of Surb Amenaprkich (951) and Surb Astvatsatsin, the arcaded book depository of 1063 and the stone gallery of the academy form a labyrinth of vaulted halls. The Zakarian family added chapels and khachkars; two kings of the Kyurikid branch lie here. The crafts school of Sanahin left copper bells and gates of legendary quality. With Haghpat it forms a UNESCO pair — the twin monasteries of the Debed valley.",
        bodyRu = "Санаин — «этот древнее того», как толкует народная этимология, показывая через долину на Ахпат, — основан в X веке на склоне Лори и стал университетом раньше, чем крепостью: академия Григор Магистра учила словесности, богословию и даже календарной науке. Церкви Сурб Аменапркич (951) и Сурб Аствацацин, аркадное книгохранилище 1063 года и каменная галерея академии образуют лабиринт сводчатых залов. Закаряны добавили часовни и хачкары; здесь лежат два царя Кюрикidской ветви. Ремесленная школа Санаина оставила медные колокола и врата легендарного качества. С Ахпатом он образует пару ЮНЕСКО — монастыри-близнецы Дебедской долины.",
        bodyHy = "Սանահինը՝ «սա հին է նրանից», ասում է ժողովրդական ստուգաբանությունը՝ ձորի մյուս կողմում ցույց տալով Հաղպատը, հիմնվել է 10-րդ դարում Լորու լանջին և ամրոցից առաջ համալսարան դարձավ. Գրիգոր Մագիստրոսի ակադեմիան ուսուցանում էր հումանիտար գիտություններ, աստվածաբանություն և նույնիսկ օրացուցային գիտություն։ Սուրբ Ամենափրկիչ (951) և Սուրբ Աստվածածին եկեղեցիները, 1063 թվականի սյունազարդ գրապահոցը և ակադեմիայի քարե պատկերասրահը թաղակապ դահլիճների լաբիրինթոս են կազմում։ Զաքարյաններն ավելացրին մատուռներ ու խաչքարեր. այստեղ ամփոփված են Կյուրիկյան ճյուղի երկու արքա։ Սանահինի արհեստի դպրոցը թողել է լեգենդար որակի պղնձե զանգեր ու դռներ։ Հաղպատի հետ այն կազմում է ՅՈՒՆԵՍԿՕ-ի զույգ՝ Դեբեդի հովտի երկվորյակ վանքերը։"
    ),
    WikiSeedArticle(
        id = "sevanavank", category = "fortresses", sortOrder = 121, section = "ancient",
        titleEn = "Sevanavank", titleRu = "Севанаванк", titleHy = "Սևանավանք",
        bodyEn = "Sevanavank stands on the peninsula that was an island until the water of Lake Sevan fell in the 20th century. Princess Mariam, widow of king Ashot I, founded the monastery in 874 as a vow: two churches of black tuff, Surb Arakelots and Surb Astvatsatsin, rose on the rock where her kin had withstood a siege. The scriptorium of Sevan kept gospels; its 'Sevan school' of illumination marks the turn of the 9th century. The stair of 1206 cut into the rock, rows of khachkars and the wind off the water make the climb a rite. From the top the lake opens ringed by mountains. Today Sevanavank is the easiest great monastery to reach from Yerevan, an hour's drive.",
        bodyRu = "Севанаванк стоит на полуострове, остававшемся островом до тех пор, пока в XX веке не упал уровень Севана. Княгиня Мариам, вдова царя Ашота I, основала монастырь в 874 году по обету: две церкви из чёрного туфа, Сурб Аракелоц и Сурб Аствацацин, поднялись на скале, где её род выдержал осаду. Скрипторий Севана хранил евангелия; «Севанская школа» миниатюры отмечает рубеж IX века. Врезанная в скалу лестница 1206 года, ряды хачкаров и ветер с воды превращают подъём в обряд. Сверху озеро открывается кольцом гор. Сегодня Севанаванк — самый доступный из больших монастырей: час от Еревана.",
        bodyHy = "Սևանավանքը կանգնած է թերակղզու վրա, որ կղզի էր մնում մինչև 20-րդ դարում Սևանա լճի ջրի նվազումը։ Իշխանուհի Մարիամը՝ Աշոտ Ա թագավորի այրին, վանքը հիմնեց 874 թվականին՝ որպես երդում. սև տուֆից երկու եկեղեցի՝ Սուրբ Առաքելոցը և Սուրբ Աստվածածինը, բարձրացան ժայռի վրա, ուր նրա տոհմը դիմացել էր պաշարմանը։ Սևանի գրչատունը պահում էր ավետարաններ. մանրանկարչության «Սևանի դպրոցը» նշում է 9-րդ դարի շրջագիծը։ 1206 թվականին ժայռի մեջ փորված աստիճանը, խաչքարերի շարքերը և ջրից եկող քամին բարձրացումը վերածում են ծեսի։ Գագաթից լիճը բացվում է լեռներով օղակված։ Այսօր Սևանավանքը Երևանից հասանելի ամենամեծ վանքն է՝ մեկ ժամ ճանապարհ։"
    ),
    WikiSeedArticle(
        id = "aghtamar", category = "fortresses", sortOrder = 122, section = "ancient",
        titleEn = "Aghtamar, church on the island", titleRu = "Ахтамар — храм на острове", titleHy = "Աղթամարը՝ կղզու տաճարը",
        bodyEn = "On the island of Aghtamar in Lake Van, king Gagik Artsruni of Vaspurakan raised in 915–921 the church of the Holy Cross — a compact cube crowned by a tent dome, wrapped in a continuous stone tapestry. Its facades carry near a hundred reliefs: Christ in glory, prophets and saints, Jonah and the whale, and along the drum — Gagik himself offering the model of the church. Friezes of grapes, lions and eagles run between the figures; inside, fragments of 10th-century frescoes survive. The monastery was the seat of the Armenian Catholicosate of Aghtamar for centuries. Restored in 2005–2007, the church again stands alone on the water against the mountains — one of the great images of medieval art.",
        bodyRu = "На острове Ахтамар озера Ван царь Гагик Арцруни Васпураканский воздвиг в 915–921 годах церковь Святого Креста — плотный куб, увенчанный шатровым куполом и окутанный сплошным каменным ковром. На её фасадах около сотни рельефов: Христос во славе, пророки и святые, Иона и кит, а по барабану — сам Гагик, подающий модель храма. Между фигурами бегут фризы из винограда, львов и орлов; внутри уцелели фрагменты фресок X века. Монастырь веками был резиденцией Ахтамарского католикосата армян. Восстановленный в 2005–2007 годах, храм снова стоит один на воде против гор — один из великих образов средневекового искусства.",
        bodyHy = "Վանա լճի Աղթամար կղզում Վասպուրականի Գագիկ Արծրունի թագավորը 915–921 թվականներին կառուցեց Սուրբ Խաչ եկեղեցին՝ սեղմ խորանարդ, թագադրված վրանաձև գմբեթով և փաթաթված անընդհատ քարե գորգով։ Նրա ճակատներին հարյուրից ավելի ռելիեֆ է. փառքի մեջ Քրիստոսը, մարգարեներն ու սուրբերը, Հովնանն ու կետը, իսկ թմբկի երկայնքով՝ ինքը Գագիկը՝ եկեղեցու մոդելը մատուցելիս։ Կերպարների միջև վազում են խաղողի, առյուծների և արծիվների քիվապատեր. ներսում պահպանվել են 10-րդ դարի որմնանկարների հատվածներ։ Վանքը դարերով եղել է հայոց Աղթամարի կաթողիկոսության նստավայրը։ 2005–2007 թվականներին վերականգնված տաճարը կրկին միայնակ կանգնած է ջրի վրա՝ լեռների դիմաց, միջնադարյան արվեստի մեծ պատկերներից մեկը։"
    ),
    WikiSeedArticle(
        id = "khorvirap", category = "fortresses", sortOrder = 123, section = "ancient",
        titleEn = "Khor Virap", titleRu = "Хор Вирап", titleHy = "Խոր Վիրապ",
        bodyEn = "Khor Virap — 'deep dungeon' — stands on a plain in sight of Mount Ararat, on the spot of ancient Artashat where the royal prison lay. Here Gregory the Illuminator was kept in a pit for thirteen years for his faith, surviving on bread thrown down by a widow, until the ailing king Trdat III remembered him in 301. Healed and baptised, the king freed Gregory — and Armenia turned Christian. The pit, three metres across and six deep, can still be entered by ladder; the monastery walls of the 17th century frame the church of Surb Astvatsatsin. For fifteen centuries pilgrims have come here to look at Ararat across the border — the mountain where, says Genesis, the Ark came to rest. The view alone is worth the road from Yerevan.",
        bodyRu = "Хор Вирап — «глубокая яма» — стоит на равнине в виду Арарата, на месте древнего Арташата, где была царская темница. Здесь Григорий Просветитель тринадцать лет содержался в яме за веру, живя на хлебе, который бросала вниз вдова, пока болеющий царь Трдат III не вспомнил о нём в 301 году. Исцелённый и крещёный, царь освободил Григория — и Армения стала христианской. В яму шириной три и глубиной шесть метров можно спуститься и сегодня по лестнице; монастырские стены XVII века обрамляют церковь Сурб Аствацацин. Пятнадцать веков паломники приходят сюда смотреть на Арарат через границу — гору, где, по Бытию, остановился ковчег. Один этот вид стоит дороги из Еревана.",
        bodyHy = "Խոր Վիրապը՝ «խոր գումար», կանգնած է հարթավայրում՝ Արարատ լեռան տեսքի տակ, հին Արտաշատի տեղում, ուր արքայական բանտն էր։ Այստեղ Գրիգոր Լուսավորիչը տասներեք տարի պահվում էր փոսում՝ հավատի համար, ապրելով այրի կնոջ նետած հացով, մինչև հիվանդ Տրդատ Գ թագավորը հիշեց նրան 301 թվականին։ Բժշկված և մկրտված արքան ազատեց Գրիգորին, և Հայաստանը դարձավ քրիստոնյա։ Երեք մետր լայնությամբ և վեց մետր խորությամբ փոս կարելի է իջնել այսօր էլ՝ աստիճանով. 17-րդ դարի վանքի պարիսպները շրջանակում են Սուրբ Աստվածածին եկեղեցին։ Տասնհինգ դար ուխտավորներ են գալիս այստեղ՝ սահմանից այն կողմ նայելու Արարատին, լեռանը, ուր, ասում է Գիրքը, կանգ առավ Նոյան տապանը։ Միայն այդ տեսարանն արժե Երևանից եկած ճանապարհը։"
    ),
    WikiSeedArticle(
        id = "khachkar", category = "culture", sortOrder = 124, section = "ancient",
        titleEn = "Khachkar, the cross-stone", titleRu = "Хачкар — крест-камень", titleHy = "Խաչքարը",
        bodyEn = "The khachkar — a stone stele with a carved cross on a rosette or sun, framed by vines and palmettes — is an art form Armenia gave the world: since the early 9th century tens of thousands have been raised, and no two are alike. The cross never stands alone: beneath it a small base with a bud, around it — the tree of life; the stone breathes like lace. Khachkars were set for salvation of a soul, in memory of a victory, as boundary signs; whole fields of them — like Noratus by Lake Sevan with its seven hundred stones — form open-air museums. The craft, passed from father to son, is on the UNESCO intangible heritage list. The finest masters — Momik, Kiram, Arakel — signed their stones like painters sign canvases.",
        bodyRu = "Хачкар — каменная стела с резным крестом на розетке или солнце, оплетённая виноградом и пальметтами, — форма искусства, подаренная Арменией миру: с начала IX века воздвигнуты десятки тысяч, и нет двух одинаковых. Крест никогда не стоит один: под ним маленькое основание с почкой, вокруг — древо жизни; камень дышит, как кружево. Хачкары ставили во спасение души, в память о победе, как межевые знаки; целые поля их — как Норатус у Севана с семьюстами камнями — образуют музеи под открытым небом. Ремесло, передаваемое от отца к сыну, внесено в список нематериального наследия ЮНЕСКО. Лучшие мастера — Момик, Кирам, Аракел — подписывали свои камни, как живописцы полотна.",
        bodyHy = "Խաչքարը՝ քարե ստելա՝ վարդյակի կամ արևի վրա փորագրված խաչով՝ որթատունկերով ու արմավենազարդերով պարփակված, արվեստի այն ձևն է, որ Հայաստանը նվիրեց աշխարհին. 9-րդ դարից սկսած կանգնեցվել են տասնյակ հազարավորներ, և երկու նման չկա։ Խաչը երբեք միայնակ չի կանգնում. նրա տակ փոքրիկ հիմք՝ բողբոջով, շուրջը՝ կյանքի ծառը. քարը շնչում է ինչպես ժանյակ։ Խաչքարներ էին դնում հոգու փրկության համար, հաղթանակի հիշատակին, որպես սահմանաքարեր. դրանց ամբողջ դաշտերը, ինչպես Սևանա լճի ափին գտնվող Նորատուսը՝ յոթ հարյուր քարով, բացօթյա թանգարաններ են կազմում։ Հորից որդու անցնող արհեստը ՅՈՒՆԵՍԿՕ-ի ոչ նյութական ժառանգության ցուցակում է։ Լավագույն վարպետները՝ Մոմիկը, Կիրամը, Առաքելը՝ ստորագրում էին իրենց քարերը, ինչպես նկարիչները՝ կտավները։"
    ),
    WikiSeedArticle(
        id = "matenadaran", category = "culture", sortOrder = 125, section = "ancient",
        titleEn = "Matenadaran, the book mountain", titleRu = "Матенадаран — гора книг", titleHy = "Մատենադարանը",
        bodyEn = "The Matenadaran in Yerevan — named for 'matenadaran', a house of books — continues the royal library of Echmiadzin, itself heir to the schools of the 5th century. It keeps some 23,000 manuscripts: gospels with jewelled covers, medical treatises, calendars, court poems, maps of the world — many saved from fire and genocide by families who buried the chests or swallowed their keys. The oldest complete book dates to 887. Here worked the school of Toros Roslin, the greatest Armenian miniaturist of the 13th century, whose pages glow with colours ground from stone. The building of 1959, a basalt colossus with the statues of Mashtots and his pupils, guards the collection above the city. A manuscript page saved here can change what the world knows about late antiquity.",
        bodyRu = "Матенадаран в Ереване — от слова «матенадаран», дом книг, — продолжает королевскую библиотеку Эчмиадзина, саму восходящую к школам V века. Он хранит около 23 000 рукописей: евангелия с окладами, медицинские трактаты, календари, дворцовые поэмы, карты мира — многие спасены от огня и геноцида семьями, зарывавшими сундуки или проглатывавшими ключи. Древнейшая полная книга датируется 887 годом. Здесь работала школа Тороса Рослина, величайшего армянского миниатюриста XIII века, чьи страницы светятся красками, стёртыми с камня. Здание 1959 года, базальтовый колосс со статуями Маштоца и его учеников, стережёт собрание над городом. Спасённая здесь страница рукописи может изменить то, что мир знает о поздней античности.",
        bodyHy = "Երևանի Մատենադարանը՝ անվանված «մատենադարան»՝ գրքերի տուն բառից, շարունակում է Էջմիածնի արքայական մատենադարանը, որն էլ 5-րդ դարի դպրոցների ժառանգորդն է։ Այն պահում է շուրջ 23 000 ձեռագիր. ոսկերիչ կազմերով ավետարաններ, բժշկական երկեր, օրացույցներ, պալատական պոեմներ, աշխարհի քարտեզներ, շատերը փրկված հրդեհից և ցեղասպանությունից ընտանիքների կողմից, որոնք թաղում էին արկղերը կամ կուլ էին տալիս դրանց բանալիները։ Ամենահին ամբողջական գիրքը թվագրվում է 887 թվականին։ Այստեղ աշխատել է Տորոս Ռոսլինի դպրոցը՝ 13-րդ դարի մեծագույն հայ մանրանկարիչը, ուր էջերը փայլում են քարից քերված ներկերով։ 1959 թվականի շենքը՝ բազալտե հսկան՝ Մաշտոցի և աշակերտների արձաններով, պահպանում է հավաքածուն քաղաքի վրա։ Այստեղ փրկված ձեռագրի մի էջ կարող է փոխել այն, ինչ աշխարհը գիտի ուշ հնագույն ժամանակների մասին։"
    ),
    WikiSeedArticle(
        id = "vardan", category = "history", sortOrder = 126, section = "ancient",
        titleEn = "Vardan Mamikonian and Avarayr", titleRu = "Вардан Мамиконян и Аварайр", titleHy = "Վարդան Մամիկոնյանը և Ավարայրը",
        bodyEn = "In 451, on the field of Avarayr by the Thmut river, a band of 66,000 Armenians faced a Sasanian army several times larger, sent to force the land back to Zoroastrian worship. Their sparapet Vardan Mamikonian had led the revolt of 449, when magnates and priests refused the fire altars. The battle was lost: Vardan and many companions fell, the survivors scattered into the fastnesses. Yet the war of Vardan's nephew Vahan Mamikonian ended in 484 with the treaty of Nvarsak, granting the Armenians freedom of faith. Yeghishe, the chronicler of the war, wrote the sentence that became the nation's oath: 'Death not understood is death; death understood is immortality.' The Church canonised Vardan and his 1,036 companions.",
        bodyRu = "В 451 году, на поле Аварайра у реки Тхмут, шестьдесят шесть тысяч армян встали против сасанидского войска в несколько раз большего, посланного вернуть страну к зороастрийскому культу. Их спарапет Вардан Мамиконян возглавил восстание 449 года, когда нахарары и священники отвергли огненные алтари. Битва была проиграна: Вардан и многие соратники пали, уцелевшие рассеялись по твердыням. Но война племянника Вардана, Вагана Мамиконяна, завершилась в 484 году договором в Нварсаке, даровавшим армянам свободу веры. Егише, летописец войны, написал фразу, ставшую клятвой нации: «Смерть непознанная — смерть; смерть познанная — бессмертие». Церковь причислила Вардана и его 1036 сподвижников к лику святых.",
        bodyHy = "451 թվականին՝ Ավարայրի դաշտում, Տղմուտ գետի ափին, վաթսունվեց հազար հայ դիմավորեց սասանյան բանակին, որ մի քանի անգամ մեծ էր և ուղարկված՝ երկիրը վերադարձնելու զրադաշտական պաշտամունքին։ Նրանց սպարապետ Վարդան Մամիկոնյանը գլխավորել էր 449 թվականի ապստամբությունը, երբ նախարարներն ու հոգևորականները մերժեցին կրակի զոհասեղանները։ Ճակատամարտը կորսվեց. Վարդանն ու շատ ընկերներ ընկան, փրկվածները ցրվեցին ամրոցները։ Բայց Վարդանի եղբորորդի Վահան Մամիկոնյանի պատերազմն ավարտվեց 484 թվականին Նվարսակի պայմանագրով, որ հայերին տվեց հավատի ազատություն։ Պատերազմի տարեգիր Եղիշեն գրեց այն նախադասությունը, որ դարձավ ազգի երդումը. «Չիմացած մահը մահ է, իմացած մահը՝ անմահություն»։ Եկեղեցին Վարդանին և նրա 1036 ընկերներին սրբացրեց։"
    ),
    WikiSeedArticle(
        id = "bagratuni", category = "history", sortOrder = 127, section = "ancient",
        titleEn = "The Bagratid kingdom", titleRu = "Царство Багратидов", titleHy = "Բագրատունիների թագավորությունը",
        bodyEn = "After four and a half centuries without a crown, Armenia rose again as a kingdom in 885, when Ashot I Bagratuni was recognised by both the Caliph and Byzantium. The Bagratid land stretched from Tashir to Vaspurakan; its wealth was not conquest but the crossroads — Dvin controlled the trade of the Ararat plain, and Ani grew into a city of a hundred churches. Ashot III the Merciful moved the capital to Ani around 961; under Smbat II and Gagik I the kingdom reached a Silver Age: bridges, churches by Trdat the architect, books and schools. Yet the branches of the house grew apart into separate kingdoms, and the empires returned: Byzantium took Ani in 1045, the Seljuks broke the country at Manzikert in 1071. The idea, though, survived every fall: a hundred years later the Rubenids raised a new crown in Cilicia.",
        bodyRu = "После четырёх с половиной веков без короны Армения снова стала царством в 885 году, когда Ашот I Багратуни был признан и халифом, и Византией. Земля Багратидов тянулась от Ташира до Васпуракана; её богатством была не война, а перекрёстки: Двин держал торговлю Араратской равнины, а Ани вырос в город ста церквей. Ашот III Милостивый перенёс столицу в Ани около 961 года; при Смбате II и Гагике I царство пережило серебряный век: мосты, церкви архитектора Трдата, книги и школы. Но ветви дома разошлись в отдельные царства, и империи вернулись: Византия взяла Ани в 1045-м, сельджуки сломали страну при Манцикерте в 1071-м. Идея, однако, пережила каждое падение: сто лет спустя Рубениды подняли новую корону в Киликии.",
        bodyHy = "Չորսուկես դար թագից հետո Հայաստանը նորից թագավորություն դարձավ 885 թվականին, երբ Աշոտ Ա Բագրատունին ճանաչվեց և՛ խալիֆի, և՛ Բյուզանդիայի կողմից։ Բագրատունիների երկիրը ձգվում էր Տաշիրից մինչև Վասպուրական. նրա հարստությունը նվաճումը չէր, այլ խաչմերուկները. Դվինը պահում էր Արարատյան դաշտի առևտուրը, իսկ Անին աճեց հարյուր եկեղեցու քաղաք։ Աշոտ Գ Ողորմածը մայրաքաղաքը տեղափոխեց Անի մոտ 961 թվականին. Սմբատ Բ-ի և Գագիկ Ա-ի օրոք թագավորությունն ապրեց արծաթե դար. կամուրջներ, ճարտարապետ Տրդատի եկեղեցիներ, գրքեր ու դպրոցներ։ Բայց տան ճյուղերը բաժանվեցին առանձին թագավորությունների, և կայսրությունները վերադարձան. Բյուզանդիան վերցրեց Անին 1045-ին, սելջուկները կոտրեցին երկիրը Մանազկերտում 1071-ին։ Գաղափարը սակայն վերապրեց ամեն անկում. հարյուր տարի անց Ռուբենյանները նոր թագ բարձրացրին Կիլիկիայում։"
    )
)
